function populateProfile(){const p=read(KEYS.profile,{}),map={profName:'fullName',profEmail:'email',profPhone:'phone',profCompany:'company',profJob:'jobTitle',profWebsite:'website',profAddress:'address',profCity:'city',profCountry:'country',profSkills:'skills'};for(const [id,k] of Object.entries(map)){const e=$('#'+id,panel);if(e)e.value=p[k]||''}const n=Object.values(p).filter(Boolean).length;if($('#profilePreview'))$('#profilePreview').innerHTML='<div class="wb-inline-note">'+n+' field(s) stored locally.</div>';if($('#formAgentFields')){const arr=Object.entries(p).filter(([,v])=>String(v||'').trim());$('#formAgentFields').innerHTML=arr.length?arr.map(([k,v])=>'<article class="wb-item"><div><strong>'+esc(k)+'</strong><p>'+esc(v)+'</p></div><div class="wb-item-actions"><button data-action="copy-value" data-value="'+esc(v)+'">Copy</button></div></article>').join(''):empty('Save a profile in Form Assistant first.')}}
let focusSeconds=1500,focusTimer=null,focusEndAt=0,focusRuns=read(KEYS.sessions,[]),lastTable=[],lastTextOutput='';
function showFocus(){const e=$('#focusTime');if(e)e.textContent=String(Math.floor(focusSeconds/60)).padStart(2,'0')+':'+String(focusSeconds%60).padStart(2,'0');const m=$('#focusMode');if(m&&focusSeconds>0&&focusTimer)m.textContent='Focus session running';const s=$('#focusStats');if(s)s.innerHTML='<p class="wb-help">'+focusRuns.length+' completed session(s) stored locally.</p>'}
function syncFocus(){if(!focusTimer)return;focusSeconds=Math.max(0,Math.ceil((focusEndAt-Date.now())/1000));if(focusSeconds===0){clearInterval(focusTimer);focusTimer=null;focusEndAt=0;if($('#focusMode'))$('#focusMode').textContent='Time is up';say('Focus session finished.')}showFocus()}
function doFocus(a){if(a==='focus-start'&&!focusTimer){if(focusSeconds===0)focusSeconds=1500;focusEndAt=Date.now()+focusSeconds*1000;focusTimer=setInterval(syncFocus,250);if($('#focusMode'))$('#focusMode').textContent='Focus session running';syncFocus()}else if(a==='focus-pause'){if(focusTimer){syncFocus();if(focusTimer){clearInterval(focusTimer);focusTimer=null;focusEndAt=0;if($('#focusMode'))$('#focusMode').textContent='Paused'}}}else if(a==='focus-reset'){if(focusTimer)clearInterval(focusTimer);focusTimer=null;focusEndAt=0;focusSeconds=1500;if($('#focusMode'))$('#focusMode').textContent='Ready for a focus session'}else if(a==='focus-complete'){if(focusTimer)syncFocus();if(focusTimer)clearInterval(focusTimer);focusTimer=null;focusEndAt=0;focusRuns.unshift({id:uid(),task:val('focusTask'),seconds:1500-focusSeconds,created:Date.now()});focusRuns=focusRuns.slice(0,100);write(KEYS.sessions,focusRuns);focusSeconds=1500;if($('#focusMode'))$('#focusMode').textContent='Session recorded';say('Session recorded.')}showFocus()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&focusTimer)syncFocus()})
function parseCSV(s,d){const rows=[];let row=[],cell='',q=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){cell+='"';i++}else q=!q}else if(c===d&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(v=>v!==''))rows.push(row);return rows}
function csvEscape(v){const s=String(v??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function renderTable(rows){lastTable=rows;const n=Math.min(30,Math.max(0,...rows.map(r=>r.length)));$('#tablePreview').innerHTML='<p class="wb-help">'+rows.length+' row(s) · '+n+' column(s). Preview limited to 150 rows.</p><div class="wb-table-wrap"><table class="wb-table"><tbody>'+rows.slice(0,150).map((r,i)=>'<tr>'+Array.from({length:n},(_,j)=>'<'+(i===0?'th':'td')+'>'+esc(r[j]||'')+'</'+(i===0?'th':'td')+'>').join('')+'</tr>').join('')+'</tbody></table></div>';say('Table parsed.')}
const stopWords=new Set('the and for with from into your you are our this that have has will can not all any use using to of in on by a an as is be or if it we they their i at about after before what how why which where when who while then than also these those were was had its per job role work skills skill experience required requirements preferred knowledge ability duties responsibilities team strong good years must plus'.split(' '));
function researchReport(topic,source){const lines=source.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),urls=[...new Set(source.match(/https?:\/\/[^\s<>"']+/g)||[])],notes=lines.filter(x=>!/^https?:\/\//i.test(x));return 'YorpHives RESEARCH BRIEF\nTopic: '+topic+'\nPrepared: '+new Date().toLocaleString()+'\n\nRESEARCH QUESTION\n'+topic+'\n\nSOURCE NOTES\n'+(notes.length?notes.map((x,i)=>(i+1)+'. '+x).join('\n'):'No descriptive source notes supplied.')+'\n\nSOURCE URLS\n'+(urls.length?urls.map((x,i)=>(i+1)+'. '+x).join('\n'):'No URLs found in notes.')+'\n\nFOLLOW-UP QUESTIONS\n- Which claims have support from more than one independent source?\n- What information may be missing or out of date?\n- Which source provides the original evidence?\n- What should be verified before drawing a conclusion?\n\nYorpHives formatted supplied material only; it did not independently verify these claims or search the live web.'}
function compareJob(spec,skills){const tokens=s=>[...new Set((s.toLowerCase().match(/[a-z][a-z0-9+#.-]{1,}/g)||[]).filter(x=>!stopWords.has(x)&&!/^\d+$/.test(x)))],req=tokens(spec),own=new Set(tokens(skills)),yes=req.filter(x=>own.has(x)),no=req.filter(x=>!own.has(x));return 'JOB KEYWORD CHECK (not a hiring prediction)\n\nMatched terms ('+yes.length+'):\n'+(yes.join(', ')||'No exact keyword matches found.')+'\n\nTerms to review ('+no.length+'):\n'+(no.join(', ')||'No missing terms in this simple comparison.')+'\n\nNEXT STEPS\n- Review actual requirements rather than relying on keyword overlap.\n- Include only skills and experience you genuinely have.\n- Prepare one real example for each important requirement.\n- Record the deadline and follow-up in Job Tracker.'}
